    let mut cmd = command();
    let completions =
        clap_complete::engine::complete(&mut cmd, vec!["--fast".into(), "".into()], 1, None)
            .unwrap()
            .into_iter()
            .map(|c| c.get_value().to_str().unwrap().to_owned())
            .collect::<Vec<_>>();
