180	impl<'s, F: Fn() -> clap::Command> CompleteEnv<'s, F> {
181	    /// Process the completion request and exit
182	    ///
183	    /// **Warning:** `stdout` should not be written to before this has had a
184	    /// chance to run.
185	    pub fn complete(self) {
186	        let args = std::env::args_os();
187	        let current_dir = std::env::current_dir().ok();
188	        if self
189	            .try_complete(args, current_dir.as_deref())
190	            .unwrap_or_else(|e| e.exit())
191	        {
192	            std::process::exit(0)
193	        }
194	    }
195	
196	    /// Process the completion request
197	    ///
198	    /// **Warning:** `stdout` should not be written to before or after this has run.
199	    ///
200	    /// Returns `true` if a command was completed and `false` if this is a regular run of your
201	    /// application
202	    pub fn try_complete(
203	        self,
204	        args: impl IntoIterator<Item = impl Into<OsString>>,
205	        current_dir: Option<&std::path::Path>,
206	    ) -> clap::error::Result<bool> {
207	        self.try_complete_(args.into_iter().map(|a| a.into()).collect(), current_dir)
208	    }
209	
210	    fn try_complete_(
211	        self,
212	        mut args: Vec<OsString>,
213	        current_dir: Option<&std::path::Path>,
214	    ) -> clap::error::Result<bool> {
215	        let Some(name) = std::env::var_os(self.var) else {
216	            return Ok(false);
217	        };
218	        if name.is_empty() || name == "0" {
219	            return Ok(false);
220	        }
221	
222	        // Ensure any child processes called for custom completers don't activate their own
223	        // completion logic.
224	        // SAFETY: should only be called during application initialization.  Yeah, this is a weak
225	        // argument but the choice is that or staying on the old edition.
226	        unsafe {
227	            std::env::remove_var(self.var);
228	        }
229	
230	        let shell = self
231	            .shells
232	            .completer_for_path(std::path::Path::new(&name))?;
233	
234	        let mut cmd = (self.factory)();
235	        cmd.build();
236	
237	        let completer = args.remove(0);
238	        let escape_index = args
239	            .iter()
240	            .position(|a| *a == "--")
241	            .map(|i| i + 1)
242	            .unwrap_or(args.len());
243	        args.drain(0..escape_index);
244	        if args.is_empty() {
245	            let mut buf = Vec::new();
246	            self.write_registration(&cmd, current_dir, shell, completer, &mut buf)?;
247	            std::io::stdout().write_all(&buf)?;
248	        } else {
249	            let mut buf = Vec::new();
250	            shell.write_complete(&mut cmd, args, current_dir, &mut buf)?;
251	            std::io::stdout().write_all(&buf)?;
252	        }
253	
254	        Ok(true)
255	    }
256	
257	    fn write_registration(
258	        &self,
259	        cmd: &clap::Command,
260	        current_dir: Option<&std::path::Path>,
261	        shell: &dyn EnvCompleter,
262	        completer: OsString,
263	        buf: &mut dyn std::io::Write,
264	    ) -> Result<(), std::io::Error> {
265	        let name = cmd.get_name();
266	        let bin = self
267	            .bin
268	            .as_deref()
269	            .or_else(|| cmd.get_bin_name())
270	            .unwrap_or_else(|| cmd.get_name());
271	        let completer = if let Some(completer) = self.completer.as_deref() {
272	            completer.to_owned()
273	        } else {
274	            let mut completer = std::path::PathBuf::from(completer);
275	            if let Some(current_dir) = current_dir {
276	                if 1 < completer.components().count() {
277	                    completer = current_dir.join(completer);
278	                }
279	            }
280	            completer.to_string_lossy().into_owned()
281	        };
282	
283	        shell.write_registration(self.var, name, bin, &completer, buf)?;
284	
285	        Ok(())
286	    }
287	}
