400	#[test]
401	fn shells_completer_for_path_finds_powershell() {
402	    const SHELLS: Shells<'_> = Shells::builtins();
403	
404	    let paths = &["/usr/bin/pwsh", "powershell.exe", "powershell_ise.exe"];
405	    for path in paths {
406	        assert!(
407	            matches!(SHELLS.completer_for_path(std::path::Path::new(path)), Ok(s) if s.name() == "powershell"),
408	            "failed to detect 'powershell' from: {path}",
409	        );
410	    }
411	}
