    // accepting only the unused values on the next empty word. `red` is
    // already selected and must not reappear, and no option name or
    // positional leaks into the mandatory segment position.
    for input in [
        "--tag=red, [TAB]",
        "--label=red, [TAB]",
        "-tred, [TAB]",
        "-t=red, [TAB]",
        "--tag red, [TAB]",
