        complete!(terminator_command(), "-tred,b[TAB]"),
        snapbox::str!["-tred,blue"]
    );
    assert_data_eq!(
        complete!(terminator_command(), "-t=red,b[TAB]"),
        snapbox::str!["-t=red,blue"]
