/// Whether a long option named `flag` exists on `cmd` under its canonical long
/// name or any visible or hidden alias.
fn long_arg_exists(cmd: &clap::Command, flag: &str) -> bool {
    cmd.get_arguments().any(|a| {
        a.get_long() == Some(flag)
            || a.get_all_aliases()
                .is_some_and(|aliases| aliases.iter().any(|alias| alias == flag))
    })
}

/// Whether a *closed* word consumed by the positional at `pos_index` cannot be
/// part of a valid command line.
///
/// Only positionals with a fixed possible-value set constrain their words: a
/// word none of the values accepts makes the line uncompletable, exactly as a
/// rejected option value does. Free-form positionals (paths, custom
/// completers, ...) accept any word, and an exhausted positional layer is left
/// lenient so root-layer candidates can still be offered behind a value.
fn positional_value_is_illegal(
    cmd: &clap::Command,
    pos_index: usize,
    value: &OsStr,
) -> bool {
    let Some(positional) = cmd.get_positionals().find(|p| p.get_index() == Some(pos_index)) else {
        return false;
    };
    let Some(possible) = possible_values(positional) else {
        return false;
    };
    let Some(value) = value.to_str() else {
        // A non-UTF-8 word cannot match a stringly possible value.
        return true;
    };
    let ignore_case = positional.is_ignore_case_set();
    !possible.collect::<Vec<_>>().iter().any(|pv| pv.matches(value, ignore_case))
}

