#![cfg(feature = "unstable-dynamic")]
use std::ffi::OsString;
use clap::Command;
fn tool() -> Command {
    Command::new("tool")
        .arg(clap::Arg::new("target").value_parser(["local","remote"]))
        .subcommand(Command::new("run").visible_alias("r")
            .arg(clap::Arg::new("profile").long("profile"))
            .arg(clap::Arg::new("run_arg").value_parser(["alpha","beta"])))
        .subcommand(Command::new("remote").visible_alias("rem")
            .arg(clap::Arg::new("url").long("url"))
            .arg(clap::Arg::new("remote_arg").value_parser(["r-a","r-b"])))
        .subcommand(Command::new("reset"))
        .subcommand(Command::new("secret-sub").hide(true))
        .arg(clap::Arg::new("secret-opt").long("secret-opt").hide(true).action(clap::ArgAction::SetTrue))
}
fn run(words: &[&str], cursor_at_last_typed: bool) -> String {
    let mut args = vec![OsString::from("tool")];
    args.extend(words.iter().map(|s| OsString::from(*s)));
    if !cursor_at_last_typed { args.push(OsString::from("")); }
    let idx = args.len() - 1;
    let mut cmd = tool();
    match clap_complete::engine::complete(&mut cmd, args, idx, None) {
        Ok(cs) => format!("Ok: {}", cs.into_iter().map(|c| c.get_value().to_string_lossy().into_owned()).collect::<Vec<_>>().join(", ")),
        Err(e) => format!("ERR: {e}"),
    }
}
#[test]
fn dbg_spec() {
    // alias enters same state; option prefixes
    println!("r --pr  (cursor): {}", run(&["r","--pr"], true));
    println!("rem --u  (cursor): {}", run(&["rem","--u"], true));
    println!("run --pr (cursor): {}", run(&["run","--pr"], true));
    // committed ambiguous after a positional
    println!("local re (closed): {}", run(&["local","re"], false));
    println!("local re (cursor): {}", run(&["local","re"], true));
    // hidden at cursor
    println!("secret- (cursor): {}", run(&["secret-"], true));
    println!("--secret (cursor): {}", run(&["--secret"], true));
    // determinism: same call x2
    let a = run(&["r"], false); let b = run(&["r"], false);
    println!("deterministic: {}", a == b);
    // canonical vs alias equivalence (next empty candidates)
    println!("run : {}", run(&["run"], false));
    println!("r   : {}", run(&["r"], false));
    println!("remote: {}", run(&["remote"], false));
    println!("rem   : {}", run(&["rem"], false));
    // edit verbatim: typing full canonical word at cursor
    println!("run[TAB]: {}", run(&["run"], true));
    println!("remote[TAB]: {}", run(&["remote"], true));
    // overlong prefix
    println!("runx (cursor): {}", run(&["runx"], true));
    println!("runx (closed): {}", run(&["runx"], false));
}
EOF
